from pathlib import Path
import re,hashlib,json
for name in ['flow.md','state-machine.md','structure.md']:
 p=Path(name); lines=p.read_text().splitlines()
 print('\\nFILE',name,'hash',hashlib.sha256(p.read_bytes()).hexdigest(),'lines',len(lines))
 for n,l in enumerate(lines,1):
  if l.startswith('#') or n<=12: print(n,l[:300])
 print('metadata lines:')
 for n,l in enumerate(lines,1):
  if len(l)<1200 and re.search(r'sha256|source_hash|source_file|excluded|MC-0|DI-0|A-0',l,re.I): print(n,l)
