 q=Path(copy); actual=hashlib.sha256(q.read_bytes()).hexdigest();print(copy,'MATCH' if h==actual else 'MISMATCH',actual)
for f,ranges in [('flow.md',[(9,32),(506,515)]),('fr-nfr.md',[(66,84),(132,147)]),('ui-mockup.html',[(1,5)])]:
